


export type CreatePickupFulfillmentDetailsInput = { /** Address where the buyer collects the order. */ "address"?: { "city": string; /** ISO 3166-1 alpha-2 country code. minLength: 2. maxLength: 2. pattern: ^[A-Z]{2}$. Example: "US". */ "country": string; "line1": string; "line2"?: string; "postal_code": string; "state": string; }; /** Instructions specific to curbside handoff. maxLength: 2048. */ "curbside_instructions"?: string; /** Buyer-reported arrival time for curbside or counter pickup. Format: date-time. */ "customer_arrived_at"?: string | globalThis.Date; /** Deadline after which an uncollected pickup should enter merchant review. Format: date-time. */ "expires_at"?: string | globalThis.Date; /** Pickup instructions for the buyer, such as where to go on arrival. */ "instructions"?: string; /** Name of the store or place where the buyer collects the order. */ "location_name"?: string; /** Width of the promised pickup window, from 0 to 86400 seconds. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. maximum: 86400. */ "pickup_window_duration_seconds"?: string; /** Expected preparation time for restaurant and made-to-order pickup, from 0 to 86400 seconds. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. maximum: 86400. */ "prep_time_duration_seconds"?: string; /** RFC3339 timestamp. Format: date-time. */ "ready_at"?: string | globalThis.Date; "timezone"?: string; /** Buyer vehicle description used for curbside handoff. maxLength: 500. */ "vehicle_description"?: string; /** RFC3339 timestamp. Format: date-time. */ "window_end_at"?: string | globalThis.Date; /** RFC3339 timestamp. Format: date-time. */ "window_start_at"?: string | globalThis.Date; };
